"""Self-contained realtime dashboard; no CDN or frontend build step."""
from __future__ import annotations
from flask import Flask, jsonify

PAGE = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pi FPGA IDS</title><style>
:root{--bg:#08111f;--p:#101d30;--line:#263a57;--txt:#e8f1ff;--mut:#90a7c8;--cyan:#38d8ff;--green:#3de29d;--amber:#ffbf55;--red:#ff687c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#173660,var(--bg) 42%);color:var(--txt);font:14px system-ui,-apple-system,Segoe UI,sans-serif}.wrap{max-width:1420px;margin:auto;padding:26px}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:22px}.brand{display:flex;gap:13px;align-items:center}.logo{width:42px;height:42px;display:grid;place-items:center;border:1px solid var(--cyan);border-radius:12px;color:var(--cyan);font-weight:800}.brand h1{font-size:20px;margin:0}.brand p{margin:3px 0;color:var(--mut);font-size:12px}.live{color:var(--mut);font-size:12px}.live i{display:inline-block;width:8px;height:8px;background:var(--green);border-radius:50%;box-shadow:0 0 12px var(--green);margin-right:7px}.grid{display:grid;gap:14px}.health{grid-template-columns:repeat(3,1fr);margin-bottom:14px}.metrics{grid-template-columns:repeat(4,1fr);margin-bottom:14px}.lower{grid-template-columns:1.3fr 1fr}.panel,.metric{background:linear-gradient(145deg,#13223a,#0c1728);border:1px solid var(--line);border-radius:14px;padding:17px;box-shadow:0 14px 30px #0002}h2,.label{margin:0;color:var(--mut);font-size:11px;letter-spacing:.09em;text-transform:uppercase}.status{font-weight:650;font-size:16px;margin-top:12px;display:flex;gap:9px;align-items:center}.badge{font-size:10px;font-weight:800;letter-spacing:.08em;padding:5px 8px;border-radius:99px;background:#173a30;color:var(--green)}.warn{background:#49371d;color:var(--amber)}.bad{background:#48202c;color:var(--red)}.detail,.sub{margin-top:8px;color:var(--mut);font:12px ui-monospace,SFMono-Regular,monospace;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.num{font-size:29px;font-weight:720;margin:8px 0 2px}.bar{height:7px;background:#091322;border-radius:99px;overflow:hidden;margin-top:13px}.bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--cyan),var(--green));transition:.4s}.result{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-top:14px}.key{background:#091422;border:1px solid #1d304d;padding:10px;border-radius:9px}.key span{color:var(--mut);font-size:10px;text-transform:uppercase}.key b{display:block;font:18px ui-monospace,monospace;margin-top:4px}.rows{margin-top:12px}.row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #1e304a}.row span{color:var(--mut)}.events{max-height:300px;overflow:auto;margin-top:12px}.event{padding:10px 0;border-bottom:1px solid #1e304a;font:12px ui-monospace,monospace}.event time{color:var(--mut);margin-right:7px}.event.error{color:#ffabb7}.event.warn{color:#ffd28b}.empty{color:var(--mut);padding:25px;text-align:center}@media(max-width:850px){.health,.metrics,.lower{grid-template-columns:1fr 1fr}.lower{grid-template-columns:1fr}}@media(max-width:520px){.wrap{padding:15px}.health,.metrics,.lower{grid-template-columns:1fr}.live{display:none}}
</style></head><body><main class="wrap"><header><div class="brand"><div class="logo">IDS</div><div><h1>Pi · FPGA Intrusion Detection</h1><p>Live operations console · UART feature inference</p></div></div><div class="live"><i></i><span id="updated">Connecting…</span></div></header>
<section class="grid health"><div class="panel"><h2>Capture link</h2><div class="status"><b id="capB" class="badge">—</b><span id="capS">Starting</span></div><div id="capD" class="detail">—</div></div><div class="panel"><h2>FPGA UART</h2><div class="status"><b id="uartB" class="badge">—</b><span id="uartS">Starting</span></div><div id="uartD" class="detail">—</div></div><div class="panel"><h2>Pipeline health</h2><div class="status"><b id="pipeB" class="badge">—</b><span id="pipeS">Waiting</span></div><div id="pipeD" class="detail">No labels available — accuracy is not shown.</div></div></section>
<section class="grid metrics"><div class="metric"><div class="label">Captured records</div><div id="captures" class="num">0</div><div id="capRate" class="sub">0.00 records/s</div><div class="bar"><i id="capBar"></i></div></div><div class="metric"><div class="label">Accepted UART results</div><div id="results" class="num">0</div><div id="resRate" class="sub">0.00 results/s</div><div class="bar"><i id="resBar"></i></div></div><div class="metric"><div class="label">Capture throughput</div><div id="speed" class="num">0 B/s</div><div id="total" class="sub">0 total bytes</div><div class="bar"><i id="speedBar"></i></div></div><div class="metric"><div class="label">Transport faults</div><div id="faults" class="num">0</div><div id="faultD" class="sub">retry 0 · timeout 0 · CRC 0</div><div class="bar"><i id="faultBar"></i></div></div></section>
<section class="grid lower"><div class="panel"><h2>Latest FPGA inference</h2><div class="result"><div class="key"><span>Sequence</span><b id="seq">—</b></div><div class="key"><span>Class ID</span><b id="class">—</b></div><div class="key"><span>Model version</span><b id="model">—</b></div><div class="key"><span>Leaf node</span><b id="leaf">—</b></div><div class="key"><span>Steps</span><b id="steps">—</b></div><div class="key"><span>Error code</span><b id="modelErr">—</b></div></div><div class="rows"><div class="row"><span>Last capture</span><b id="lastCap">—</b></div><div class="row"><span>Last result</span><b id="lastRes">—</b></div><div class="row"><span>Last source</span><b id="source">—</b></div></div></div><div class="panel"><h2>Operational events</h2><div id="events" class="events"><div class="empty">No events yet</div></div></div></section></main>
<script>const $=x=>document.getElementById(x),num=x=>new Intl.NumberFormat().format(x||0),tm=x=>x?new Date(x).toLocaleString():'—',rate=x=>(x||0).toFixed(2),size=x=>{x=x||0;for(const u of ['B','KB','MB','GB']){if(x<1024||u==='GB')return (x<10&&u!=='B'?x.toFixed(1):Math.round(x))+' '+u;x/=1024}},put=(x,v)=>$(x).textContent=v;function connection(id,v){let b=$(id+'B');b.textContent=(v.state||'unknown').toUpperCase();b.className='badge '+(v.state==='connected'?'':v.state==='degraded'?'warn':'bad');put(id+'S',v.label||'Unknown');put(id+'D',v.detail||'—')}function draw(s){connection('cap',s.connections.capture);connection('uart',s.connections.uart);let fault=s.timeouts+s.crc_errors;connection('pipe',{state:fault?'degraded':'connected',label:fault?'Attention needed':'Operational',detail:fault?'Review transport errors below.':'No labels available — accuracy is not shown.'});put('captures',num(s.capture_count));put('results',num(s.result_count));put('capRate',rate(s.capture_rate_pps)+' records/s');put('resRate',rate(s.result_rate_pps)+' results/s');put('speed',size(s.capture_bytes_per_second)+'/s');put('total',size(s.capture_bytes)+' total bytes');put('faults',num(s.retries+s.timeouts+s.crc_errors));put('faultD',`retry ${s.retries} · timeout ${s.timeouts} · CRC ${s.crc_errors}`);[['capBar',s.capture_rate_pps*10],['resBar',s.result_rate_pps*10],['speedBar',s.capture_bytes_per_second/1024],['faultBar',(s.retries+s.timeouts+s.crc_errors)*10]].forEach(x=>$(x[0]).style.width=Math.min(100,x[1])+'%');[['seq',s.last_sequence],['class',s.class_id],['model',s.model_version],['leaf',s.leaf_node],['steps',s.step_count],['modelErr',s.error_code]].forEach(x=>put(x[0],x[1]??'—'));put('lastCap',tm(s.last_capture_at));put('lastRes',tm(s.last_result_at));put('source',s.last_source||'—');$('events').innerHTML=(s.events||[]).slice().reverse().map(e=>`<div class="event ${e.level}"><time>${tm(e.time)}</time>${e.message}</div>`).join('')||'<div class="empty">No events yet</div>';put('updated','Updated '+new Date().toLocaleTimeString())}async function poll(){try{let r=await fetch('/api/status',{cache:'no-store'});if(!r.ok)throw Error();draw(await r.json())}catch(e){put('updated','Dashboard connection lost')}}poll();setInterval(poll,1000)</script></body></html>'''

def make_app(state):
    app = Flask(__name__)
    @app.get("/api/status")
    def status(): return jsonify(state.snapshot())
    @app.get("/")
    def dashboard(): return PAGE
    return app
